```solidity
pragma solidity ^0.8.0;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

contract DecentralizedVoting is AccessControl, ReentrancyGuard {
    struct Voter {
        bool voted;
        uint vote;
        address delegate;
    }

    struct Proposal {
        string description;
        uint voteCount;
    }

    mapping(address => Voter) public voters;
    Proposal[] public proposals;
    uint public votingPeriod;
    uint public endTime;

    event Voted(address indexed voter, uint proposalIndex, uint vote);
    event ProposalAdded(string description);
    event ProposalRemoved(uint proposalIndex);

    constructor(uint _votingPeriod) {
        _setupRole(DEFAULT_ADMIN_ROLE, msg.sender);
        votingPeriod = _votingPeriod;
        endTime = block.timestamp + _votingPeriod;
    }

    modifier onlyAdmin() {
        require(hasRole(DEFAULT_ADMIN_ROLE, msg.sender), "Not an admin");
        _;
    }

    function addProposal(string memory _description) public onlyAdmin {
        proposals.push(Proposal({description: _description, voteCount: 0}));
        emit ProposalAdded(_description);
    }

    function removeProposal(uint _proposalIndex) public onlyAdmin {
        require(_proposalIndex < proposals.length, "Invalid proposal index");
        emit ProposalRemoved(_proposalIndex);
    }

    function vote(uint _proposalIndex) public nonReentrant {
        Voter storage sender = voters[msg.sender];
        require(!sender.voted, "Already voted");
        require(block.timestamp < endTime, "Voting period has ended");

        sender.voted = true;
        sender.vote = _proposalIndex;

        Proposal storage proposal = proposals[_proposalIndex];
        proposal.voteCount += 1;

        emit Voted(msg.sender, _proposalIndex, proposal.voteCount);
    }

    function getWinningProposal() public view returns (uint winningProposalIndex) {
        uint winningVoteCount = 0;
        for (uint i = 0; i < proposals.length; i++) {
            if (proposals[i].voteCount > winningVoteCount) {
                winningVoteCount = proposals[i].voteCount;
                winningProposalIndex = i;
            }
        }
    }

    function getVoterBalance(address _voter) public view returns (uint) {
        return address(this).balance;
    }

    function deposit() public payable {
        require(msg.value > 0, "Deposit value must be greater than 0");
    }

    function withdraw(uint _amount) public onlyAdmin {
        require(_amount <= address(this).balance, "Insufficient balance");
        payable(msg.sender).transfer(_amount);
    }

    function getBalance() public view returns (uint) {
        return address(this).balance;
    }
}
```

This smart contract includes the following features:
1. **Access Control**: Using OpenZeppelin's `AccessControl` to manage roles and permissions.
2. **Reentrancy Guard**: To prevent reentrancy attacks.
3. **Voter Management**: Each voter can only vote once per proposal.
4. **Proposal Management**: Admins can add and remove proposals.
5. **Voting Mechanism**: Voters can vote on proposals, and the contract keeps track of votes.
6. **Winning Proposal Calculation**: A function to determine the winning proposal.
7. **Balance Management**: Functions to deposit and withdraw funds, ensuring only admins can withdraw.
8. **Event Emission**: Events to log key actions for transparency and auditing.

This contract is a starting point and can be further expanded with additional features such as time-based voting, delegate voting, and more sophisticated access control mechanisms.

